def set_stock_modes(apps, schema_editor):
    """MacBooks keep a count per configuration; every other model gets one
    shared count, starting from its largest configuration count."""
    Product = apps.get_model('store', 'Product')
    for product in Product.objects.select_related('brand').prefetch_related('variants'):
        if product.brand and product.brand.name.strip().lower() == 'apple':
            product.stock_mode = 'variant'
        else:
            product.stock_mode = 'model'
            product.stock = max((v.stock for v in product.variants.all()), default=0)
        product.save(update_fields=['stock_mode', 'stock'])


